        pm.expect(jsonData.user_id).to.exist;
    });

    pm.test("User ID is a number", function () {
        pm.expect(jsonData.user_id).to.be.a("number");
    });

} else if (pm.response.code === 400) {

    pm.test("Status code is 400", function () {
        pm.expect(pm.response.code).to.eql(400);
    });

    pm.test("Success is false", function () {
        pm.expect(jsonData.success).to.eql(false);
    });

    pm.test("Error message exists", function () {
        pm.expect(jsonData.message).to.exist;
    });

} else if (pm.response.code === 401) {

    pm.test("Status code is 401", function () {
        pm.expect(pm.response.code).to.eql(401);
    });

    pm.test("Authentication error message exists", function () {
        pm.expect(jsonData.message).to.exist;
    });

} else if (pm.response.code === 403) {

    pm.test("Status code is 403", function () {
        pm.expect(pm.response.code).to.eql(403);
    });

    pm.test("Access denied message exists", function () {
        pm.expect(jsonData.message).to.exist;
    });

} else if (pm.response.code === 409) {

    pm.test("Status code is 409", function () {
        pm.expect(pm.response.code).to.eql(409);
    });

    
    pm.test("Duplicate email message is correct", function () {
        pm.expect(jsonData.message).to.eql("Email already exists");
    });

} else if (pm.response.code === 500) {

    pm.test("Server error should not occur", function () {
        pm.expect.fail("Server error occurred. Check backend console.");
    });

} else {

    pm.test("Unexpected status code", function () {
        pm.expect.fail(
            "Unexpected status code: " + pm.response.code
        );
    });
}

